#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock environment variables for test\nexport PR_TITLE="Add new feature and fix bug"\nexport GITHUB_TOKEN="dummy"\n\n# Capture script output\noutput=$(bash "$(dirname "$0")/../src/labeler.sh")\n\n# Expected labels: bug, enhancement, 🚀 (emoji)\nif [[ "$output" != *"bug"* ]]; then\n  echo "Missing bug label"\n  exit 1\nfi\nif [[ "$output" != *"enhancement"* ]]; then\n  echo "Missing enhancement label"\n  exit 1\nfi\nif [[ "$output" != *"🚀"* ]]; then\n  echo "Missing emoji label"\n  exit 1\fi\n\necho "All tests passed"
